WITH src AS (SELECT *, CAST(salary AS INT) salary_int FROM employees WHERE is_remote = TRUE), summary AS (SELECT CASE WHEN job_title IN ('Analyst', 'Manager') THEN 'group_a' ELSE 'other' END job_title_group, MIN(salary_int) min_salary_int FROM src GROUP BY CASE WHEN job_title IN ('Analyst', 'Manager') THEN 'group_a' ELSE 'other' END) SELECT * FROM summary WHERE min_salary_int > 44 ORDER BY job_title_group;
